/*
 * boneMapping.ts - Maps GLB model node names to application bone IDs and regions
 * The GLB model from AnatomyTOOL has right-side bones (.r suffix) that need mirroring
 * 
 * Structure:
 *   "Bones" group (node 36) → midline/axial bones (no .r suffix)
 *   "Bones_right" group (node 135) → right-side bones (.r suffix)
 *   "Cartilages_right" group (node 146) → costal cartilages (.r suffix)
 *   Left-side bones are generated by mirroring right-side bones (scale X by -1)
 */

export type RegionId =
  | 'skull'
  | 'spine'
  | 'thorax'
  | 'upper-limb-left'
  | 'upper-limb-right'
  | 'pelvis'
  | 'lower-limb-left'
  | 'lower-limb-right';

export interface BoneMappingEntry {
  /** Application-level bone ID used in BONE_INFO, pathology, etc. */
  appBoneId: string;
  /** Display name in Chinese */
  nameCn: string;
  /** Display name in English */
  nameEn: string;
  /** Region this bone belongs to */
  region: RegionId;
  /** Whether this bone should be mirrored to create a left-side counterpart */
  mirror: boolean;
  /** The mirrored bone's appBoneId (if mirror=true) */
  mirrorAppBoneId?: string;
}

/**
 * Maps GLB node names → application bone metadata.
 * Key = exact node.name from the GLB file.
 * 
 * Midline bones (in "Bones" group) have no .r suffix and mirror=false.
 * Right-side bones (in "Bones_right" group) have .r suffix and mirror=true.
 */
