/**
 * Build a reverse lookup: appBoneId → BoneMappingEntry
 */
export const APP_BONE_LOOKUP: Record<string, BoneMappingEntry & { glbNodeName: string }> = {};
for (const [glbName, entry] of Object.entries(GLB_NODE_TO_BONE)) {
  APP_BONE_LOOKUP[entry.appBoneId] = { ...entry, glbNodeName: glbName };
  // Also register mirrored left-side bones
  if (entry.mirror && entry.mirrorAppBoneId) {
    const leftRegion = entry.region.replace('-right', '-left') as RegionId;
    APP_BONE_LOOKUP[entry.mirrorAppBoneId] = {
      ...entry,
      appBoneId: entry.mirrorAppBoneId,
      nameCn: entry.nameCn.replace('（右）', '（左）').replace('(R)', '(L)'),
      nameEn: entry.nameEn.replace('(R)', '(L)'),
      region: leftRegion === entry.region ? entry.region : leftRegion,
      glbNodeName: glbName + '_mirror',
      mirror: false,
    };
  }
}

/** Total bone count for display */
export const TOTAL_BONE_COUNT = Object.keys(APP_BONE_LOOKUP).length;
